tasks.check:
set -eo pipefail
WORK=/home/bcorfman/dev/ringer-work/factory-station7-spend
mkdir -p "$WORK/out"
[ -e frontend/node_modules ] || ln -s /home/bcorfman/dev/freytag-forge/frontend/node_modules frontend/node_modules
git add -A -- frontend/e2e
bad=$(git diff --cached --name-only | grep -vxF -e frontend/e2e/blind-player.js -e frontend/e2e/blind-player.spec.js -e frontend/e2e/blind-player.test.js || true)
[ -z "$bad" ] || { echo "files outside ownership staged: $bad"; exit 1; }
grep -q "player_usage" frontend/e2e/blind-player.spec.js || { echo "spec does not write player_usage"; exit 1; }
if grep -n -E "console\.(log|error).*(API_KEY|environment)" frontend/e2e/blind-player.js; then echo "must not log environment values"; exit 1; fi
cd frontend
start=$(date +%s)
node --test e2e/blind-player.test.js e2e/merge-blind-player.test.js
took=$(( $(date +%s) - start ))
echo "node tests took $took s (budget 30 s)"
[ "$took" -le 30 ] || { echo "node tests over the 30 s budget"; exit 1; }
# independent probe: a fake OpenAI client with real-shaped usage, a retry, and a response without usage
probe="$WORK/out/js-probe.out"
node --input-type=module - > "$probe" 2>&1 <<'JS'
import { askPlayer } from "./e2e/blind-player.js";
const body = (command, usage) => ({ ok: true, status: 200, json: async () => ({ output_text: JSON.stringify({ command }), ...(usage ? { usage } : {}) }) });
const seq = [
  body("Search the desk drawer", { input_tokens: 1000, input_tokens_details: { cached_tokens: 400 }, output_tokens: 50 }),
  body("Open the drawer.", { input_tokens: 2000, input_tokens_details: { cached_tokens: 0 }, output_tokens: 70 }),
  body("Open the door.", null),
];
let i = 0;
const fetchImpl = async () => seq[i++];
const counter = { calls: 0 };
const environment = { OPENAI_API_KEY: "x", BLIND_PLAYER_PROFILE: "canonical" };
const first = await askPlayer({ transcript: "t", status: "s", environment, fetchImpl, counter });
if (first !== "Open the drawer.") throw new Error("retry path changed: " + first);
if (counter.calls !== 2 || counter.input_tokens !== 3000 || counter.cached_input_tokens !== 400 || counter.output_tokens !== 120) throw new Error("usage not accumulated across the retry: " + JSON.stringify(counter));
await askPlayer({ transcript: "t", status: "s", environment, fetchImpl, counter });
if (counter.calls !== 3 || counter.input_tokens !== 3000 || counter.output_tokens !== 120) throw new Error("a response without usage must add nothing: " + JSON.stringify(counter));
console.log("probe ok", JSON.stringify(counter));
JS
cat "$probe"
grep -q "probe ok" "$probe" || { echo "probe failed"; exit 1; }
cd ..
git diff --cached > "$WORK/out/js-usage.patch"
test -s "$WORK/out/js-usage.patch"
